export type RetryOptions = { readonly attempts: number; readonly baseDelayMs: number; readonly maxDelayMs: number };
export class ValidationError extends Error {}
export const isRetryable = (error: unknown): boolean => !(error instanceof ValidationError);

const jitter = (ms: number) => ms * (0.5 + Math.random());

export const delayFor = (attempt: number, options: RetryOptions): number => {
  const capped = Math.min(options.baseDelayMs * 2 ** attempt, options.maxDelayMs);
  return jitter(capped);
};

export async function retry<A>(run: () => Promise<A>, options: RetryOptions): Promise<A> {
  let lastError: unknown;
  for (let attempt = 0; attempt < options.attempts; attempt++) {
    try {
      return await run();
    } catch (error) {
      lastError = error;
      await new Promise((resolve) => setTimeout(resolve, delayFor(attempt, options)));
    }
  }
  throw lastError;
}

