import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { delayFor, retry, ValidationError } from "./retry.ts";

beforeEach(() => vi.useFakeTimers());
afterEach(() => vi.useRealTimers());

describe("retry", () => {
    it("returns the first success", async () => {
  let calls = 0;
  const result = retry(async () => {
    calls++;
    if (calls < 2) throw new Error("flaky");
    return "ok";
  }, { attempts: 3, baseDelayMs: 1, maxDelayMs: 5 });
  await vi.runAllTimersAsync();
  await expect(result).resolves.toBe("ok");
    });
  it("never retries a ValidationError", async () => {
    let calls = 0;
    const result = retry(async () => { calls++; throw new ValidationError("bad"); }, { attempts: 3, baseDelayMs: 1, maxDelayMs: 5 });
    await expect(result).rejects.toBeInstanceOf(ValidationError);
    expect(calls).toBe(1);
  });
  it("keeps every delay at or below maxDelayMs", () => {
    for (let attempt = 0; attempt < 20; attempt++) expect(delayFor(attempt, { attempts: 20, baseDelayMs: 10, maxDelayMs: 100 })).toBeLessThanOrEqual(100);
  });
});
